<?php
declare(strict_types=1);
session_start();
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/AssistenteAplicacaoService.php';
require_once dirname(__DIR__) . '/components/pagina_padrao.php';
require_once dirname(__DIR__) . '/components/botoes_crud.php';
if (empty($_SESSION['autenticado'])) { http_response_code(401); exit('Sessao expirada.'); }
if (strtoupper((string)($_SESSION['usuario']['codigo_perfil'] ?? '')) !== 'ADMINISTRADOR') { http_response_code(403); exit('Acesso restrito ao perfil ADMINISTRADOR.'); }
$env=GreenPortalDatabase::env(); $pdo=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');
$user=(int)($_SESSION['usuario']['codusuario']??0); if(empty($_SESSION['migracao_menu_csrf'])) $_SESSION['migracao_menu_csrf']=bin2hex(random_bytes(32)); $csrf=(string)$_SESSION['migracao_menu_csrf'];
$msg='';$err='';
try { if($_SERVER['REQUEST_METHOD']==='POST'){ if(!hash_equals($csrf,(string)($_POST['csrf']??''))) throw new RuntimeException('Token de seguranca invalido.');
  AssistenteAplicacaoService::chamarProcedure($pdo,'sp_migracao_menu_nao_mapeado_associar',[(int)$_POST['codregistro'],trim((string)$_POST['banco_destino']),((int)($_POST['codmenu_destino']??0)), $user, strtoupper(trim((string)$_POST['status']))]);
  $msg='Validacao do menu registrada.';
} } catch(Throwable $e){$err=$e->getMessage();}
$destino=trim((string)($_GET['destino']??'')); $status=strtoupper(trim((string)($_GET['status']??'PENDENTE'))); $busca=trim((string)($_GET['q']??''));
$total=(int)(AssistenteAplicacaoService::chamarProcedure($pdo,'sp_migracao_menus_nao_mapeados_count',[$destino,$status,$busca])[0]['total']??0);
$rows=AssistenteAplicacaoService::chamarProcedure($pdo,'sp_migracao_menus_nao_mapeados_listar',[$destino,$status,$busca,500,0]);
$menus=$pdo->query("SELECT codmenu,codigo,label,modulo FROM menus WHERE ativo=1 ORDER BY COALESCE(modulo,''),label")->fetchAll(PDO::FETCH_ASSOC);
$destinos=$pdo->query("SELECT DISTINCT banco_destino FROM migracao_menus_nao_mapeados ORDER BY banco_destino")->fetchAll(PDO::FETCH_COLUMN);
$esc=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Menus de migração para validação</title>
<link href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2" rel="stylesheet"><link href="../assets/vendor/bootstrap-icons/font/bootstrap-icons.min.css?v=2" rel="stylesheet"><link href="../assets/css/app.css" rel="stylesheet"><link href="../assets/css/main.css?v=15" rel="stylesheet"><?php greenPortalEstiloPagina(); ?><style>.migration-grid-fragment{display:flex;flex-direction:column;height:100vh;padding:10px 12px;gap:8px}.menu-grid-scroll{flex:1 1 auto;overflow:auto}.migration-grid td{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.migration-grid tbody tr{cursor:pointer}.grid-secondary{color:#6b8279;font-size:10px}.association-help{font-size:12px;color:#52665d}.migration-grid .form-select{min-width:270px}</style></head><body>
<section class="setup-fragment menu-grid-fragment migration-grid-fragment grid-ready"><div class="crud-toolbar menu-grid-toolbar"><a class="btn btn-sm btn-outline-secondary grid-crud-button" href="administracao_migracao_empresas.php" title="Voltar para solicitações"><i class="bi bi-arrow-left"></i></a><span class="ms-2 fw-semibold">Menus não mapeados</span><span class="association-help ms-2">Permissões não concedidas até a validação administrativa.</span></div>
<?php if($msg):?><div class="alert alert-success py-2 mb-0"><?=$esc($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger py-2 mb-0"><?=$esc($err)?></div><?php endif;?>
<form class="row g-2 align-items-end" method="get"><div class="col-md-3"><label class="form-label small">Banco destino</label><select class="form-select form-select-sm" name="destino"><option value="">Todos</option><?php foreach($destinos as $d):?><option value="<?=$esc($d)?>" <?=$destino===$d?'selected':''?>><?=$esc($d)?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label small">Status</label><select class="form-select form-select-sm" name="status"><option value="">Todos</option><?php foreach(['PENDENTE','VALIDADO','IGNORADO'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label small">Buscar código, label ou banco</label><input class="form-control form-control-sm" name="q" value="<?=$esc($busca)?>"></div><div class="col-md-2"><button class="btn btn-sm btn-primary" type="submit"><i class="bi bi-search me-1"></i>Filtrar</button></div></form>
<div class="association-help"><?=$total?> ocorrência(s). Escolha o menu universal correspondente e grave como <b>VALIDADO</b>. Isso registra o mapeamento para revisão; não altera permissões existentes automaticamente.</div>
<div class="menu-grid-scroll"><table class="table table-sm menu-batch-grid migration-grid"><thead><tr><th>Destino</th><th>Grupo legado</th><th>Menu legado (ID)</th><th>Código legado</th><th>Descrição</th><th>Associação</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$esc($r['banco_destino'])?></td><td><?=$esc($r['codgrupo_legado'])?></td><td><?=$esc($r['codmenu_legado'])?></td><td title="<?=$esc($r['codigo_legado'])?>"><?=$esc($r['codigo_legado'])?></td><td title="<?=$esc($r['label_legado'])?>"><?=$esc($r['label_legado'])?></td><td><?php if($r['codmenu_destino']):?><span class="grid-secondary"><?=$esc($r['label_destino'])?></span><?php else:?><span class="text-muted">Pendente</span><?php endif;?></td><td><span class="badge text-bg-<?=strtoupper($r['status'])==='VALIDADO'?'success':(strtoupper($r['status'])==='IGNORADO'?'secondary':'warning')?>"><?=$esc($r['status'])?></span></td><td><button class="btn btn-sm btn-outline-primary" type="button" data-associate data-id="<?=$esc($r['codregistro'])?>" data-destino="<?=$esc($r['banco_destino'])?>" data-label="<?=$esc($r['label_legado'])?>" data-menu="<?=$esc($r['codmenu_destino']??0)?>" title="Associar menu"><i class="bi bi-link-45deg"></i></button></td></tr><?php endforeach;?></tbody></table></div><nav class="grid-pagination"><span><?=$total?> registro(s)</span></nav></section>
<div class="modal fade" id="associationModal" tabindex="-1" aria-labelledby="associationTitle" aria-hidden="true"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title" id="associationTitle">Associar menu universal</h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fechar"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=$esc($csrf)?>"><input type="hidden" name="codregistro" id="associationId"><input type="hidden" name="banco_destino" id="associationDestino"><p class="small text-muted" id="associationLegacy"></p><label class="form-label" for="associationMenu">Menu universal</label><select class="form-select" name="codmenu_destino" id="associationMenu"><option value="0">Nenhum</option><?php foreach($menus as $m):?><option value="<?=$esc($m['codmenu'])?>"><?=$esc(($m['modulo']?$m['modulo'].' / ':'').$m['label'])?> (<?=$esc($m['codigo'])?>)</option><?php endforeach;?></select><label class="form-label mt-3" for="associationStatus">Resultado</label><select class="form-select" name="status" id="associationStatus"><option>PENDENTE</option><option>VALIDADO</option><option>IGNORADO</option></select></div><div class="modal-footer"><button class="btn btn-sm btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-sm btn-success" type="submit"><i class="bi bi-check2 me-1"></i>Salvar validação</button></div></form></div></div></div>
<script src="../assets/vendor/bootstrap/js/bootstrap.bundle.min.js?v=2"></script><script>(function(){var modal=document.getElementById('associationModal'),instance=bootstrap.Modal.getOrCreateInstance(modal);document.querySelectorAll('[data-associate]').forEach(function(button){button.addEventListener('click',function(){document.getElementById('associationId').value=button.dataset.id;document.getElementById('associationDestino').value=button.dataset.destino;document.getElementById('associationLegacy').textContent='Menu legado: '+(button.dataset.label||'(sem label)')+' | Banco: '+button.dataset.destino;document.getElementById('associationMenu').value=button.dataset.menu||'0';document.getElementById('associationStatus').value=button.dataset.menu&&button.dataset.menu!=='0'?'VALIDADO':'PENDENTE';instance.show();});});}());</script></body></html>
